const config = $('Watchdog Configuration').item.json;
const recentErrors = $('Query Recent Workflow Errors').all();
const stuckItems = $('Query Stuck Processing Items').all();
const staleSyncs = $('Query Stale Calendar Syncs').all();

const criticalWorkflows = config.criticalWorkflows.split(',').map(w => w.trim());

// Build alert report
let alerts = [];
let severity = 'info';
let alertNeeded = false;

// Check workflow errors
if (recentErrors.length > 0) {
  for (const error of recentErrors) {
    const isCritical = criticalWorkflows.some(cw => 
      error.json.workflow_name.toLowerCase().includes(cw.toLowerCase())
    );

    alerts.push({
      type: 'workflow_error',
      severity: isCritical ? 'critical' : 'warning',
      workflow: error.json.workflow_name,
      count: error.json.error_count,
      lastError: error.json.last_error_at,
      messages: error.json.error_messages
    });

    if (isCritical) {
      severity = 'critical';
    } else if (severity !== 'critical') {
      severity = 'warning';
    }
    alertNeeded = true;
  }
}

// Check stuck items
for (const item of stuckItems) {
  if (parseInt(item.json.stuck_count) > 0) {
    const checkType = item.json.check_type;
    let itemSeverity = 'warning';

    // Emergency maintenance stuck is critical
    if (checkType === 'maintenance_tickets') {
      itemSeverity = 'critical';
      if (severity !== 'critical') severity = 'critical';
    } else if (severity !== 'critical' && severity !== 'warning') {
      severity = 'warning';
    }

    alerts.push({
      type: 'stuck_processing',
      severity: itemSeverity,
      checkType: checkType,
      count: item.json.stuck_count,
      oldestStuck: item.json.oldest_stuck
    });
    alertNeeded = true;
  }
}

// Check stale syncs (lower priority)
if (staleSyncs.length > 0) {
  alerts.push({
    type: 'stale_calendar_sync',
    severity: 'info',
    count: staleSyncs.length,
    properties: staleSyncs.map(s => s.json.property_name).join(', ')
  });
  if (!alertNeeded && staleSyncs.length >= 3) {
    alertNeeded = true;
  }
}

// Format alert message
let alertMessage = '';
if (alertNeeded) {
  const emoji = severity === 'critical' ? '🚨' : (severity === 'warning' ? '⚠️' : 'ℹ️');
  alertMessage = `${emoji} **WATCHDOG ALERT** - ${severity.toUpperCase()}\n`;
  alertMessage += `Time: ${new Date().toISOString()}\n\n`;

  // Group by type
  const workflowErrors = alerts.filter(a => a.type === 'workflow_error');
  const stuckProcessing = alerts.filter(a => a.type === 'stuck_processing');
  const staleCalendars = alerts.filter(a => a.type === 'stale_calendar_sync');

  if (workflowErrors.length > 0) {
    alertMessage += '**Workflow Errors:**\n';
    for (const err of workflowErrors) {
      alertMessage += `• ${err.workflow}: ${err.count} error(s)\n`;
      alertMessage += `  Last: ${err.lastError}\n`;
      if (err.messages) {
        alertMessage += `  Msg: ${err.messages.substring(0, 100)}...\n`;
      }
    }
    alertMessage += '\n';
  }

  if (stuckProcessing.length > 0) {
    alertMessage += '**Stuck Processing:**\n';
    for (const stuck of stuckProcessing) {
      alertMessage += `• ${stuck.checkType}: ${stuck.count} stuck since ${stuck.oldestStuck}\n`;
    }
    alertMessage += '\n';
  }

  if (staleCalendars.length > 0) {
    alertMessage += '**Stale Calendar Syncs:**\n';
    alertMessage += `• ${staleCalendars[0].count} properties not synced in 48h\n`;
    alertMessage += `  Properties: ${staleCalendars[0].properties}\n`;
  }

  alertMessage += '\n---\nCheck n8n dashboard for details.';
}

return {
  alertNeeded,
  severity,
  alertCount: alerts.length,
  alerts,
  alertMessage,
  alertTelegramChatId: config.alertTelegramChatId,
  alertWhatsAppNumber: config.alertWhatsAppNumber,
  alertPreferredPlatform: config.alertPreferredPlatform,
  checkTimestamp: new Date().toISOString()
};

// Final summary
const healthData = $('Analyze System Health').item.json;

return {
  watchdog_run_completed: true,
  timestamp: new Date().toISOString(),
  alert_sent: healthData.alertNeeded,
  severity: healthData.severity,
  issues_found: healthData.alertCount,
  next_check_in: '15 minutes'
};
